class Tool {
  constructor(name) {
    this.name = name;
  }

  use() {
    return `${this.name} is being used.`;
  }
}

class Hammer extends Tool {
  constructor(name, weight) {
    super(name);
    this.name = name; 
    this.weight = weight;
  }

  #strikeAction() {
    const effectiveWeight = this.weight; 
    return `striking with ${Number(effectiveWeight).toFixed(0)}kg impact`;
  }

  use() {
    const parentMessage = super.use();
    const strikeMessage = this.#strikeAction();
    return [parentMessage.trimEnd(), "and", strikeMessage].join(' '); 
  }
}

